/**
 * Giờ làm việc mặc định của học viện.
 *
 * ĐÂY LÀ CHỖ CẦN SỬA. Em đặt tạm 8 giờ sáng tới 8 giờ tối, làm cả bảy ngày,
 * vì spa và học viện thẩm mỹ thường đông nhất cuối tuần. Anh sửa lại cho đúng
 * thực tế rồi dán vào node Code trong workflow.
 */
const GIO_LAM_VIEC = {
	mo: '08:00',
	dong: '20:00',
	// 0 là Chủ nhật, 1 là thứ Hai, ... 6 là thứ Bảy.
	// Để rỗng là làm cả tuần. Muốn nghỉ Chủ nhật thì ghi [0].
	ngayNghi: [],
	// Lệch múi giờ so với UTC. Việt Nam là 7.
	lechMuiGio: 7,
};

/** '08:30' thành 510 phút tính từ nửa đêm. Sai định dạng thì trả về null. */
function phutTrongNgay(hhmm) {
	const khop = /^(\d{1,2}):(\d{2})$/.exec(String(hhmm).trim());
	if (!khop) return null;
	const gio = Number(khop[1]);
	const phut = Number(khop[2]);
	if (gio > 24 || phut > 59) return null;
	return gio * 60 + phut;
}

/**
 * Đổi thời điểm thành số phút tính từ mốc 1970, theo giờ địa phương.
 *
 * Phải tự chặn null và chuỗi rỗng trước khi gọi new Date, vì new Date(null)
 * không ra ngày sai mà ra đúng mốc 1970. Để nó lọt thì một lead thiếu cột
 * thoi_gian_vao sẽ bị tính là đã chờ mấy chục năm và lập tức báo trễ hạn.
 */
function phutDiaPhuong(thoiDiem, lechMuiGio) {
	if (thoiDiem === null || thoiDiem === undefined) return null;
	if (typeof thoiDiem === 'string' && thoiDiem.trim() === '') return null;

	const d = thoiDiem instanceof Date ? thoiDiem : new Date(thoiDiem);
	const mili = d.getTime();
	if (!Number.isFinite(mili)) return null;
	return Math.floor(mili / 60000) + lechMuiGio * 60;
}

/** 0 là Chủ nhật. Ngày 0 của mốc 1970 là thứ Năm nên cộng 4. */
function thuTrongTuan(chiSoNgay) {
	return (((chiSoNgay + 4) % 7) + 7) % 7;
}

/**
 * Số phút làm việc giữa hai thời điểm.
 *
 * @param {string|Date} tu    thời điểm bắt đầu, ví dụ lúc lead vào
 * @param {string|Date} den   thời điểm kết thúc, thường là bây giờ
 * @param {object} cauHinh    ghi đè GIO_LAM_VIEC, không bắt buộc
 * @returns {{phut: number, hopLe: boolean, lyDo?: string}}
 */
function phutLamViecGiua(tu, den, cauHinh) {
	const c = Object.assign({}, GIO_LAM_VIEC, cauHinh || {});

	const mo = phutTrongNgay(c.mo);
	const dong = phutTrongNgay(c.dong);
	if (mo === null || dong === null) {
		return { phut: 0, hopLe: false, lyDo: 'gio_mo_dong_sai_dinh_dang' };
	}
	if (dong <= mo) {
		return { phut: 0, hopLe: false, lyDo: 'gio_dong_khong_sau_gio_mo' };
	}

	const batDau = phutDiaPhuong(tu, c.lechMuiGio);
	const ketThuc = phutDiaPhuong(den, c.lechMuiGio);
	if (batDau === null || ketThuc === null) {
		return { phut: 0, hopLe: false, lyDo: 'thoi_diem_sai_dinh_dang' };
	}
	// Mốc kết thúc trước mốc bắt đầu thì coi như chưa trôi phút nào, không
	// phải lỗi. Đồng hồ lệch vài giây là chuyện thường.
	if (ketThuc <= batDau) return { phut: 0, hopLe: true };

	const ngayNghi = new Set((c.ngayNghi || []).map(Number));
	if (ngayNghi.size >= 7) {
		return { phut: 0, hopLe: false, lyDo: 'nghi_ca_bay_ngay' };
	}

	const ngayDau = Math.floor(batDau / 1440);
	const ngayCuoi = Math.floor(ketThuc / 1440);

	let tong = 0;
	for (let ngay = ngayDau; ngay <= ngayCuoi; ngay++) {
		if (ngayNghi.has(thuTrongTuan(ngay))) continue;
		const khungMo = ngay * 1440 + mo;
		const khungDong = ngay * 1440 + dong;
		const giao = Math.min(ketThuc, khungDong) - Math.max(batDau, khungMo);
		if (giao > 0) tong += giao;
	}

	return { phut: tong, hopLe: true };
}

/** Đang trong giờ làm việc hay không. Dùng để không gửi cảnh báo lúc nửa đêm. */
function dangTrongGioLamViec(thoiDiem, cauHinh) {
	const c = Object.assign({}, GIO_LAM_VIEC, cauHinh || {});
	const mo = phutTrongNgay(c.mo);
	const dong = phutTrongNgay(c.dong);
	const moc = phutDiaPhuong(thoiDiem, c.lechMuiGio);
	if (mo === null || dong === null || moc === null) return false;

	const ngay = Math.floor(moc / 1440);
	if (new Set((c.ngayNghi || []).map(Number)).has(thuTrongTuan(ngay))) return false;

	const trongNgay = moc - ngay * 1440;
	return trongNgay >= mo && trongNgay < dong;
}

// ---------------------------------------------------------------------------
// NGƯỠNG CANH. Sửa ở đây.
// ---------------------------------------------------------------------------
const HAN_PHUT = 120;        // lời hứa gọi khách trong 2 giờ làm việc
const SAP_HAN_PHUT = 90;     // báo sớm khi còn 30 phút, để còn kịp cứu

const bayGio = new Date();
const rows = $input.all().map((i) => i.json).filter((r) => r && r.lead_id);

const treHan = [];
const sapHan = [];
const loi = [];

for (const r of rows) {
	// Đã gọi rồi thì thôi. Chỉ canh lead chưa ai gọi lần đầu.
	const daGoi = String(r.thoi_gian_goi_dau || '').trim() !== '';
	if (daGoi) continue;

	// Lead đã chốt hoặc đã mất thì không canh nữa.
	const trangThai = String(r.trang_thai || '').trim();
	if (['da_chot', 'mat', 'da_dang_ky'].includes(trangThai)) continue;

	const kq = phutLamViecGiua(r.thoi_gian_vao, bayGio);

	if (!kq.hopLe) {
		// Không im lặng bỏ qua. Thiếu mốc thời gian cũng là một lỗi cần người xem.
		loi.push({
			lead_id: r.lead_id,
			ho_ten: r.ho_ten || '',
			sdt: r.sdt || '',
			nguoi_phu_trach: r.nguoi_phu_trach || '',
			ly_do: kq.lyDo,
			thoi_gian_vao_goc: r.thoi_gian_vao || '',
		});
		continue;
	}

	const daCanhBao = String(r.muc_canh_bao || '').trim();

	const ban = {
		lead_id: r.lead_id,
		ho_ten: r.ho_ten || 'Chua ro ten',
		sdt: r.sdt || '',
		nguon: r.nguon || '',
		khoa_quan_tam: r.khoa_quan_tam || '',
		nguoi_phu_trach: r.nguoi_phu_trach || 'Chua gan',
		thoi_gian_vao: r.thoi_gian_vao || '',
		phut_da_cho: kq.phut,
	};

	// Chỉ báo khi mức nặng hơn lần đã báo, nhờ vậy không kêu lại mỗi 15 phút.
	if (kq.phut > HAN_PHUT && daCanhBao !== 'tre_han') {
		treHan.push(Object.assign({}, ban, { muc_canh_bao: 'tre_han' }));
	} else if (kq.phut > SAP_HAN_PHUT && kq.phut <= HAN_PHUT && daCanhBao === '') {
		sapHan.push(Object.assign({}, ban, { muc_canh_bao: 'sap_han' }));
	}
}

const canhBao = treHan.concat(sapHan);
const trongGio = dangTrongGioLamViec(bayGio);

// Ngoài giờ làm việc thì im, không gửi và cũng không đánh dấu.
// Lý do: dựng người quản lý lúc 2 giờ sáng để báo một lead mà tới sáng mới gọi
// được thì chỉ gây phiền. Vì không đánh dấu nên lần chạy đầu tiên sau giờ mở
// cửa sẽ báo lại đầy đủ, không mất việc nào.
const coViecCanBao = trongGio && (canhBao.length > 0 || loi.length > 0);

// Trả về một item cho mỗi lead cần báo, kèm một item tóm tắt ở đầu để node sau
// biết có gì mà báo hay không.
const tomTat = {
	la_tom_tat: true,
	so_tre_han: treHan.length,
	so_sap_han: sapHan.length,
	so_loi_du_lieu: loi.length,
	co_viec_can_bao: coViecCanBao,
	trong_gio_lam_viec: trongGio,
	thoi_diem_kiem: bayGio.toISOString(),
	danh_sach: canhBao,
	loi_du_lieu: loi,
};

return [{ json: tomTat }].concat(canhBao.map((c) => ({ json: c })));

// Soạn một tin gọn cho người quản lý đọc trên điện thoại.
const tomTat = $input.all().map((i) => i.json).find((j) => j.la_tom_tat);
if (!tomTat) return [];

const dong = [];
const gio = (iso) => {
	const d = new Date(iso);
	if (!Number.isFinite(d.getTime())) return String(iso || '');
	// Giờ Việt Nam cho người đọc.
	return new Date(d.getTime() + 7 * 3600 * 1000)
		.toISOString()
		.slice(0, 16)
		.replace('T', ' ');
};

const treHan = tomTat.danh_sach.filter((c) => c.muc_canh_bao === 'tre_han');
const sapHan = tomTat.danh_sach.filter((c) => c.muc_canh_bao === 'sap_han');

if (treHan.length) {
	dong.push(`TRE HAN: ${treHan.length} lead da qua 2 gio ma chua ai goi`);
	for (const c of treHan) {
		dong.push(
			`  ${c.ho_ten} | ${c.sdt} | ${c.nguoi_phu_trach} | cho ${c.phut_da_cho} phut lam viec | vao luc ${gio(c.thoi_gian_vao)}`,
		);
	}
	dong.push('');
}

if (sapHan.length) {
	dong.push(`SAP HET HAN: ${sapHan.length} lead con duoi 30 phut`);
	for (const c of sapHan) {
		dong.push(`  ${c.ho_ten} | ${c.sdt} | ${c.nguoi_phu_trach} | cho ${c.phut_da_cho} phut lam viec`);
	}
	dong.push('');
}

if (tomTat.loi_du_lieu.length) {
	dong.push(`LOI DU LIEU: ${tomTat.loi_du_lieu.length} lead khong tinh duoc han`);
	for (const l of tomTat.loi_du_lieu) {
		dong.push(`  ${l.lead_id} | ${l.ho_ten} | ${l.sdt} | ly do: ${l.ly_do} | cot thoi_gian_vao: "${l.thoi_gian_vao_goc}"`);
	}
	dong.push('');
}

dong.push(`Kiem luc ${gio(tomTat.thoi_diem_kiem)} gio Viet Nam.`);

const tieuDe = treHan.length
	? `[DrSkin] ${treHan.length} lead TRE HAN goi dau`
	: sapHan.length
		? `[DrSkin] ${sapHan.length} lead sap het han 2 gio`
		: '[DrSkin] Loi du lieu bang LEAD';

return [{ json: { tieu_de: tieuDe, noi_dung: dong.join('\n') } }];

// Chỉ gửi đúng hai cột cần ghi đè, tránh ghi nhầm lên cột khác.
return $input.all()
	.map((i) => i.json)
	.filter((j) => !j.la_tom_tat)
	.map((c) => ({ json: { lead_id: c.lead_id, muc_canh_bao: c.muc_canh_bao } }))

// Đổi mỗi lead cần báo thành một dòng của bảng HOAT_DONG.
const items = $input.all().map((i) => i.json).filter((j) => !j.la_tom_tat);
const bayGio = new Date().toISOString();
return items.map((c) => ({
	json: {
		id: `${c.lead_id}-${c.muc_canh_bao}-${bayGio.slice(0, 16)}`,
		lead_id: c.lead_id,
		loai: c.muc_canh_bao === 'tre_han' ? 'tre_han_goi_dau' : 'sap_het_han_goi_dau',
		noi_dung: `Da cho ${c.phut_da_cho} phut lam viec ma chua co cuoc goi dau. Nguoi phu trach: ${c.nguoi_phu_trach}.`,
		nguoi_thuc_hien: 'He thong',
		thoi_gian: bayGio,
	},
}))
